const stocks={NVDA:{name:'英伟达',price:'$182.41',change:'+2.41%',trend:'up',status:'证据充分',sector:'半导体'},AAPL:{name:'苹果',price:'$246.80',change:'−0.68%',trend:'down',status:'部分完成',sector:'消费电子'},MSFT:{name:'微软',price:'$511.20',change:'+0.34%',trend:'up',status:'数据延迟',sector:'软件'}},watch=new Set(['NVDA','AAPL']);
const $=s=>document.querySelector(s), $$=s=>document.querySelectorAll(s);let current='search';
function nav(view){current=view;$$('.view').forEach(x=>x.classList.toggle('active',x.id==='view-'+view));$$('.nav-item').forEach(x=>x.classList.toggle('active',x.dataset.view===view));const titles={search:'搜索与即时分析',watchlist:'我的自选股',close:'收盘报告',history:'历史复盘',analysis:'分析执行',report:'单股研究报告'};$('#pageTitle').textContent=titles[view]||'FinSight';if(view==='watchlist')renderWatch()}
function toast(t){const x=$('#toast');x.textContent=t;x.style.display='block';setTimeout(()=>x.style.display='none',2400)}
function renderSearch(q=''){const box=$('#searchResults');if(!q){box.innerHTML='';return}const key=q.toUpperCase(), found=Object.entries(stocks).filter(([k,v])=>k.includes(key)||v.name.includes(q));box.innerHTML=found.length?found.map(([k,v])=>`<div class="result-card"><div><strong>${k}</strong><small>${v.name} · ${v.sector}</small><p><span class="tag">Mock Data</span> ${v.status} · ${v.price}</p></div><button class="button" data-analyze="${k}">分析</button></div>`).join(''):`<div class="empty-state"><div class="empty-icon">⌕</div><h3>没有找到匹配标的</h3><p>请尝试 NVDA、AAPL 或 MSFT。原型暂不连接外部数据源。</p></div>`}
function runAnalysis(k){const v=stocks[k];nav('analysis');$('#analysisTitle').textContent=`${k} · ${v.name}分析执行` ;$('#analysisState').textContent='加载中';$('#analysisBody').innerHTML=`<div class="analysis-card"><p class="muted">正在按研究路径准备 Mock Data…</p><div class="progress"><i></i></div><div class="agent-list"><div class="agent"><b>行情与技术面</b><span>已完成 · 延迟 15 分钟</span></div><div class="agent"><b>基本面与公告</b><span>已完成 · SEC Mock</span></div><div class="agent"><b>多空证据</b><span>执行中…</span></div><div class="agent"><b>风险校验</b><span>等待输入</span></div></div></div>`;setTimeout(()=>{if(current!=='analysis')return;$('#analysisState').textContent=v.status;$('#analysisBody').innerHTML=`<div class="analysis-card"><p><b>任务状态：</b>${v.status}　<span class="tag">Mock Data</span></p><p class="muted">数据截止：2026-09-20 16:00 ET · 行情源为演示数据</p><div class="agent-list"><div class="agent"><b>行情与技术面</b><span>✓ 已完成</span></div><div class="agent"><b>基本面与公告</b><span>✓ 已完成</span></div><div class="agent"><b>多空证据</b><span>${k==='MSFT'?'! 数据延迟':'✓ 已完成'}</span></div><div class="agent"><b>风险校验</b><span>${k==='MSFT'?'! 部分完成':'✓ 已完成'}</span></div></div><button class="button" style="margin-top:22px" data-report="${k}">查看报告</button></div>`},650)}
function showReport(k){const v=stocks[k];nav('report');$('#reportTitle').textContent=`${k} · ${v.name}研究报告`;$('#reportBody').innerHTML=`<div class="report-grid"><div class="report-card"><span class="tag">Mock Data · ${v.status}</span><h3>市场概览</h3><div class="metric-row"><span class="metric">${v.price}</span><b class="${v.trend}">${v.change}</b></div><p class="muted">数据截止 2026-09-20 16:00 ET · 允许延迟 5–15 分钟</p><hr><h3>结论分层</h3><div class="evidence"><div><b>事实</b><p>收盘价与当日变化来自行情 Mock Data。</p></div><button data-source="事实来源">来源卡片</button></div><div class="evidence"><div><b>计算</b><p>涨跌幅 =（当前价 − 前收）÷ 前收，保留两位小数。</p></div><button data-source="计算口径">口径</button></div><div class="evidence"><div><b>推断</b><p>${k==='MSFT'?'证据不足，暂不形成方向性判断。':'动量与事件证据暂时同向，但不代表未来收益。'}</p></div><button data-source="推断依据">依据</button></div><div class="evidence"><div><b>风险</b><p>数据可能延迟；不构成投资建议，需核验原始来源。</p></div><button data-source="风险提示">风险卡</button></div></div><div class="report-card"><h3>证据与状态</h3><div class="evidence"><div><b>行情数据</b><p>Mock Market Feed · 2026-09-20</p></div><span class="pill blue">可用</span></div><div class="evidence"><div><b>公司公告</b><p>SEC Filing Mock · 原文定位演示</p></div><span class="pill blue">可用</span></div><div class="evidence"><div><b>新闻情绪</b><p>${k==='AAPL'?'来源同步延迟，结论降级':'已完成来源排序与核验'}</p></div><span class="pill ${k==='AAPL'?'orange':'blue'}">${k==='AAPL'?'延迟':'可用'}</span></div><button class="button ghost" data-add-watch="${k}">☆ 加入自选股</button></div></div>`}
function renderWatch(){const body=$('#watchBody');$('#watchCount').textContent=watch.size;body.innerHTML=[...watch].map(k=>{const v=stocks[k];return `<article class="watch-card"><header><h3>${k}</h3><span class="tag">Mock Data</span></header><p>${v.name} · ${v.sector}</p><span class="price">${v.price}</span> <b class="${v.trend}">${v.change}</b><p>状态：${v.status}</p><div class="watch-actions"><button class="text-btn" data-report="${k}">查看报告 →</button><button class="text-btn" data-remove="${k}">移除</button></div></article>`}).join('')||'<div class="empty-state"><h3>自选股还是空的</h3><p>从搜索结果添加你想持续关注的标的。</p></div>'}
document.addEventListener('click',e=>{const t=e.target.closest('[data-view]');if(t)nav(t.dataset.view);const a=e.target.closest('[data-analyze]');if(a)runAnalysis(a.dataset.analyze);const r=e.target.closest('[data-report]');if(r)showReport(r.dataset.report);const add=e.target.closest('[data-add-watch]');if(add){watch.add(add.dataset.addWatch);renderWatch();toast(`已加入 ${add.dataset.addWatch} 自选股`)}const rm=e.target.closest('[data-remove]');if(rm){watch.delete(rm.dataset.remove);renderWatch();toast('已从自选股移除')}const src=e.target.closest('[data-source]');if(src){$('#modalTitle').textContent=src.dataset.source;$('#modalText').textContent='这是可展开的模拟来源卡片，用于演示报告中的证据追溯路径。原型未连接真实 API。';$('#modalMeta').textContent='来源：Mock Data · 定位：演示 · 采集时间：2026-09-20';$('#modal').classList.add('show')}});$('#modalClose').onclick=()=>$('#modal').classList.remove('show');$('#addWatch').onclick=()=>{const k=prompt('输入要加入的代码（NVDA / AAPL / MSFT）');if(k&&stocks[k.toUpperCase()]){watch.add(k.toUpperCase());renderWatch();toast(`已加入 ${k.toUpperCase()}`)}else if(k)toast('原型仅支持 NVDA、AAPL、MSFT')};$('#searchForm').onsubmit=e=>{e.preventDefault();renderSearch($('#tickerInput').value.trim())};$('#tickerInput').oninput=e=>renderSearch(e.target.value.trim());renderSearch('');
function addReportReview(k){const card=document.querySelector('#reportBody .report-grid .report-card');if(!card)return;const block=document.createElement('div');block.innerHTML=`<h3>多空与审查</h3><div class="evidence"><div><b>多头观点</b><p>支持因素仅作研究假设，必须回到来源和截止时间核验。</p></div><button data-source="多头证据">证据</button></div><div class="evidence"><div><b>空头观点</b><p>延迟数据、替代解释和事件反转可能削弱当前判断。</p></div><button data-source="空头证据">证据</button></div><div class="evidence"><div><b>Evidence Auditor</b><p>来源与时间字段为演示检查；${k==='MSFT'?'证据不足，报告降级。':'已完成演示审计。'}</p></div><span class="pill ${k==='MSFT'?'orange':'blue'}">${k==='MSFT'?'证据不足':'已审查'}</span></div><div class="evidence"><div><b>Risk Agent</b><p>数据延迟、遗漏事件和替代解释仍需人工核验。</p></div><span class="pill orange">风险提示</span></div><div class="evidence"><div><b>Judge 综合结论</b><p>仅作 Mock Data 流程演示，不构成投资建议。</p></div><span class="tag">演示结论</span></div>`;card.appendChild(block)}
const _showReport=showReport;showReport=function(k){_showReport(k);addReportReview(k)};
